// Production-side tests for the private live BTC snapshot routes. Fixtures are SYNTHETIC (generated by the monitor-side builder, which is not part
// of this deployment); the routes and validator under test are self-contained.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import express from 'express';
import { validateLiveSnapshot, LIVE_LIMITS, LIVE_MODE } from '../flow/live-validate.js';
import { createFlowLiveRouter } from '../flow/live-routes.js';
import { verifyToken, createToken } from '../auth/jwt.js';

const fx = (n) => JSON.parse(readFileSync(fileURLToPath(new URL(`./fixtures/flow/${n}.synthetic.json`, import.meta.url)), 'utf8'));
const NORMAL = fx('live-snapshot-normal'); const EVENT = fx('live-snapshot-event'); const WITHHELD = fx('live-snapshot-withheld');
const cap = (s) => Date.parse(s.observation.capturedAt) / 1000;
const clone = (o) => JSON.parse(JSON.stringify(o));
const SECRET = 'x'.repeat(40);

test('fixtures validate at their capture time; event and withheld shapes are consistent', () => {
  for (const s of [NORMAL, EVENT, WITHHELD]) assert.equal(validateLiveSnapshot(s, { nowSec: cap(s) + 30 }).ok, true);
  assert.equal(NORMAL.verdict, 'normal'); assert.equal(NORMAL.event, null); assert.equal(EVENT.verdict, 'event'); assert.ok(EVENT.event.ratioToTypical >= 3);
  assert.equal(WITHHELD.verdict, 'withheld'); assert.ok(WITHHELD.quality.reasons.length > 0); assert.equal(LIVE_MODE, 'live-monitoring');
});

test('validator rejects forged, corrupted, stale and mislabelled payloads with fixed reasons', () => {
  const now = cap(NORMAL) + 30;
  const reason = (base, mut, nowSec = now) => { const s = clone(base); mut(s); const r = validateLiveSnapshot(s, { nowSec }); assert.equal(r.ok, false); return r.reason; };
  assert.equal(reason(NORMAL, (s) => { s.mode = 'demo-replay'; }), 'wrong-mode');
  assert.equal(reason(NORMAL, (s) => { s.mode = 'recorded-observation'; }), 'wrong-mode');
  assert.equal(reason(NORMAL, (s) => { s.schemaVersion = 2; }), 'unsupported-version');
  assert.equal(reason(NORMAL, (s) => { s.trades = [{ price: 1 }]; }), 'unknown-field');
  assert.equal(reason(NORMAL, (s) => { s.asset = 'ETH'; }), 'wrong-asset');
  assert.equal(reason(NORMAL, (s) => { s.source.venue = 'Synthetic demo'; }), 'bad-source');
  assert.equal(reason(NORMAL, () => {}, now + 3600), 'stale-snapshot');
  assert.equal(reason(NORMAL, () => {}, cap(NORMAL) - 3600), 'future-timestamp');
  assert.equal(reason(NORMAL, (s) => { s.observation.capturedAt = 'yesterday'; }), 'bad-timestamp');
  assert.equal(reason(NORMAL, (s) => { s.verdict = 'event'; }), 'inconsistent-verdict');
  assert.equal(reason(NORMAL, (s) => { s.verdict = 'event'; s.assessment = 'unusual-activity'; }), 'inconsistent-event');
  assert.equal(reason(NORMAL, (s) => { s.quality.state = 'withheld'; }), 'inconsistent-verdict');
  assert.equal(reason(NORMAL, (s) => { s.quality.reasons = ['x); DROP']; }), 'bad-quality');
  assert.equal(reason(NORMAL, (s) => { s.activity.notionalUsd = Number.NaN; }), 'bad-activity');
  assert.equal(reason(NORMAL, (s) => { s.baseline.eligible = false; }), 'inconsistent-verdict');
  assert.equal(reason(NORMAL, (s) => { s.series.push(s.series[0]); }), 'bad-series');
  for (const bad of ['nope', null, [], 7]) assert.equal(validateLiveSnapshot(bad).reason, 'not-an-object');
  const e = cap(EVENT) + 30;
  assert.equal(reason(EVENT, (s) => { s.event.ratioToTypical = 1.2; }, e), 'event-below-threshold');
  assert.equal(reason(EVENT, (s) => { s.event.notionalUsd *= 5; }, e), 'event-window-mismatch');
  assert.equal(reason(EVENT, (s) => { s.baseline.eligible = false; }, e), 'inconsistent-verdict');
  assert.equal(reason(EVENT, (s) => { s.quality.coverageVerified = false; }, e), 'inconsistent-quality');
});

const fakeAuth = (req, res, next) => (verifyToken((req.headers.authorization ?? '').replace(/^Bearer /, '')) ? next() : res.status(401).json({ error: 'Unauthorized' }));
async function serve(opts = {}) {
  const clk = { t: (cap(NORMAL) + 30) * 1000 };
  const app = express(); app.use('/api/flow', createFlowLiveRouter({ requireAuth: fakeAuth, publishSecret: SECRET, nowMs: () => clk.t, minPublishGapMs: 0, ...opts }));
  const server = await new Promise((r) => { const s = app.listen(0, '127.0.0.1', () => r(s)); });
  const base = `http://127.0.0.1:${server.address().port}/api/flow/live`;
  const user = { authorization: `Bearer ${createToken(7, 'u@example.com')}` };
  const pub = (body, headers = { authorization: `Bearer ${SECRET}` }, raw = false) => fetch(`${base}/publish`, { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: raw ? body : JSON.stringify(body) });
  return { clk, base, user, pub, get: (headers = user) => fetch(base, { headers }), close: () => new Promise((r) => server.close(r)) };
}

test('publishing is DISABLED without a configured secret of >= 32 characters; reading still needs a user token', async () => {
  for (const publishSecret of [undefined, '', 'short']) {
    const s = await serve({ publishSecret });
    try {
      for (const auth of [{}, { authorization: 'Bearer short' }, { authorization: `Bearer ${SECRET}` }]) assert.equal((await s.pub(NORMAL, auth)).status, 503);
      assert.equal((await s.get({})).status, 401);
      const b = await (await s.get()).json(); assert.equal(b.state, 'no-snapshot'); assert.equal(b.snapshot, undefined);
    } finally { await s.close(); }
  }
});

test('publish needs the secret; read needs a valid user token; both fail closed', async () => {
  const s = await serve();
  try {
    assert.equal((await s.pub(NORMAL, {})).status, 401);
    assert.equal((await s.pub(NORMAL, { authorization: 'Bearer wrong' })).status, 401);
    assert.equal((await s.pub(NORMAL, { authorization: `Bearer ${createToken(7)}` })).status, 401);
    assert.equal((await s.get({})).status, 401);
    assert.equal((await s.get({ authorization: 'Bearer garbage' })).status, 401);
    assert.equal((await s.get({ authorization: `Bearer ${SECRET}` })).status, 401);
    assert.equal((await s.get()).headers.get('cache-control'), 'no-store');
  } finally { await s.close(); }
});

test('no snapshot after a restart is explicit; then the validated snapshot is served; a silent publisher turns it stale', async () => {
  const s = await serve();
  try {
    let b = await (await s.get()).json();
    assert.equal(b.state, 'no-snapshot'); assert.equal(b.reason, 'backend-restarted');
    assert.equal((await s.pub(NORMAL)).status, 200);
    b = await (await s.get()).json();
    assert.equal(b.state, 'ok'); assert.equal(b.snapshot.verdict, 'normal'); assert.equal(b.snapshot.mode, 'live-monitoring');
    s.clk.t += (LIVE_LIMITS.maxAgeSeconds + 5) * 1000;
    b = await (await s.get()).json();
    assert.equal(b.state, 'stale'); assert.equal(b.reason, 'publisher-silent'); assert.equal(b.snapshot, undefined);
  } finally { await s.close(); }
});

test('forged, corrupted, oversized, replayed and demo payloads are refused and never served', async () => {
  const s = await serve();
  try {
    const demo = JSON.parse(readFileSync(fileURLToPath(new URL('./fixtures/flow/live-snapshot-normal.synthetic.json', import.meta.url)), 'utf8')); demo.mode = 'demo-replay';
    assert.equal((await s.pub(demo)).status, 422);
    const r = await s.pub({ ...NORMAL, verdict: 'event' }); assert.equal(r.status, 422); assert.doesNotMatch(await r.text(), /event/);
    assert.equal((await s.pub('{"mode": ', undefined, true)).status, 400);
    assert.equal((await s.pub(JSON.stringify({ ...NORMAL, pad: 'x'.repeat(40_000) }), undefined, true)).status, 413);
    assert.equal((await s.pub([1, 2, 3])).status, 422);
    assert.equal((await (await s.get()).json()).state, 'no-snapshot');
    assert.equal((await s.pub(NORMAL)).status, 200);
    assert.equal((await s.pub(NORMAL)).status, 409);
    const older = clone(NORMAL); older.observation.capturedAt = new Date(Date.parse(NORMAL.observation.capturedAt) - 1000).toISOString();
    assert.equal((await s.pub(older)).status, 409);
  } finally { await s.close(); }
});

test('publish rate limit protects the held snapshot', async () => {
  const s = await serve({ minPublishGapMs: 5000 });
  try { assert.equal((await s.pub(NORMAL)).status, 200); assert.equal((await s.pub(NORMAL)).status, 429); } finally { await s.close(); }
});

test('server.js mounts the router before the global JSON parser, with the real auth middleware, and adds nothing else', () => {
  const src = readFileSync(fileURLToPath(new URL('../server.js', import.meta.url)), 'utf8');
  const mount = src.indexOf("app.use('/api/flow', createFlowLiveRouter({ requireAuth }))");
  assert.ok(mount > 0, 'mount present');
  assert.ok(mount < src.indexOf("app.use(express.json({ limit: '5mb' }))"), 'mounted before the global parser');
  assert.match(src, /import \{ requireAuth \} from '\.\/auth\/middleware\.js'/);
  const flowSrc = ['../flow/live-routes.js', '../flow/live-validate.js'].map((f) => readFileSync(fileURLToPath(new URL(f, import.meta.url)), 'utf8').replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '')).join('\n');
  assert.doesNotMatch(flowSrc, /from '\.\/(monitor|store|detector|buckets|kraken|collector|live-snapshot)|better-sqlite3|node:fs|node:child_process|fetch\(|https?:\/\//);
});
